@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

<PageTitle>Shipments Dashboard</PageTitle>

<h1>Shipments Dashboard</h1>

<button class="btn btn-success mb-3" @onclick="ShowCreateForm">+ New Shipment</button>

@if (_showCreateForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5>Create New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input @bind="_newShipment.Origin" placeholder="Origin" class="form-control" />
                </div>
                <div class="col-md-3">
                    <input @bind="_newShipment.Destination" placeholder="Destination" class="form-control" />
                </div>
                <div class="col-md-3">
                    <input @bind="_newShipment.CustomerEmail" placeholder="Customer Email" class="form-control" />
                </div>
                <div class="col-md-3">
                    <input @bind="_newShipment.EstimatedDelivery" type="date" class="form-control" />
                </div>
                <div class="col-md-9">
                    <input @bind="_newShipment.Description" placeholder="Description" class="form-control" />
                </div>
                <div class="col-md-3">
                    <button class="btn btn-primary w-100" @onclick="CreateShipment">Create</button>
                </div>
            </div>
        </div>
    </div>
}

@if (_loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (_shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input @bind="_filterText" @bind:event="oninput" placeholder="Filter by destination or tracking number..." class="form-control" style="max-width: 400px;" />
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td><code>@shipment.TrackingNumber</code></td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                value="@((int)shipment.Status)"
                                @onchange="e => UpdateStatus(shipment.Id, e)">
                            @foreach (ShipmentStatus status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@((int)status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment> _shipments = [];
    private bool _loading = true;
    private bool _showCreateForm;
    private string _filterText = string.Empty;
    private Shipment _newShipment = new();

    private IEnumerable<Shipment> FilteredShipments => string.IsNullOrWhiteSpace(_filterText)
        ? _shipments
        : _shipments.Where(s =>
            s.Destination.Contains(_filterText, StringComparison.OrdinalIgnoreCase) ||
            s.TrackingNumber.Contains(_filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        _loading = true;
        _shipments = await ShipmentService.GetAllShipmentsAsync();
        _loading = false;
    }

    private void ShowCreateForm() => _showCreateForm = !_showCreateForm;

    private async Task CreateShipment()
    {
        await ShipmentService.CreateShipmentAsync(_newShipment);
        _newShipment = new();
        _showCreateForm = false;
        await LoadShipments();
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, status);
            await LoadShipments();
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input @bind="_trackingNumber" @onkeydown="HandleKeyDown" placeholder="Enter tracking number (e.g., SHP-20260707-123456)" class="form-control" />
            <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
        </div>
    </div>
</div>

@if (_searching)
{
    <p><em>Searching...</em></p>
}
else if (_searched && _shipment == null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number "<strong>@_searchedNumber</strong>". Please check and try again.
    </div>
}
else if (_shipment != null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Shipment <code>@_shipment.TrackingNumber</code></h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(_shipment.Status) fs-6">@GetStatusDisplayText(_shipment.Status)</span></dd>

                        <dt>Origin</dt>
                        <dd>@_shipment.Origin</dd>

                        <dt>Destination</dt>
                        <dd>@_shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Estimated Delivery</dt>
                        <dd>
                            @if (_shipment.EstimatedDelivery.HasValue)
                            {
                                <span class="fs-5">@_shipment.EstimatedDelivery.Value.ToString("dddd, MMMM dd, yyyy")</span>
                            }
                            else
                            {
                                <span class="text-muted">Not yet determined</span>
                            }
                        </dd>

                        <dt>Description</dt>
                        <dd>@(string.IsNullOrWhiteSpace(_shipment.Description) ? "—" : _shipment.Description)</dd>

                        <dt>Shipped On</dt>
                        <dd>@_shipment.CreatedAt.ToString("MMMM dd, yyyy")</dd>
                    </dl>
                </div>
            </div>

            @* Progress visualization *@
            <div class="mt-3">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(_shipment.Status)"
                         role="progressbar"
                         style="width: @(GetProgressPercent(_shipment.Status))%">
                        @_shipment.Status
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string _trackingNumber = string.Empty;
    private string _searchedNumber = string.Empty;
    private Shipment? _shipment;
    private bool _searching;
    private bool _searched;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(_trackingNumber)) return;

        _searching = true;
        _searched = false;
        _shipment = null;

        _shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(_trackingNumber.Trim());
        _searchedNumber = _trackingNumber.Trim();
        _searching = false;
        _searched = true;
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await TrackShipment();
        }
    }

    private static string GetStatusDisplayText(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "Pending Pickup",
        ShipmentStatus.PickedUp => "Picked Up",
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        ShipmentStatus.Delivered => "Delivered",
        ShipmentStatus.Delayed => "Delayed",
        _ => status.ToString()
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 50,
        _ => 0
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-primary"
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

